mapper.select:
SELECT T.*,
a.name AS asset_name,
a.serial_num as asset_serial_num,
a.depart_num as asset_depart_num,
a.function_type as asset_function_type,
a.site_uid as asset_site_uid,
a.clinical_dept_name as asset_clinical_dept_name,
a.clinical_dept_uid as asset_clinical_dept_uid,
a.clinical_dept_id as asset_clinical_dept_id,
a.location_name as asset_location_name,
a.mvs_equip as asset_mvs_equip,
a.id as asset_id,
a.uid as asset_uid,
a.status as asset_status,
a.uid AS asset_uid
FROM v2_pm_order T
LEFT JOIN mvs_ib_mapping m1 ON T.asset_uid = m1.mvs_ib_uid
LEFT JOIN mvs_ib_mapping m2 ON T.asset_uid = m2.e_home_ib_uid AND m1.ib_id IS NULL
LEFT JOIN asset_info a ON COALESCE(m1.ib_id, m2.ib_id) = a.id
WHERE 1=1

    and t.rule_level = CAST(#{ruleLevel, jdbcType=INTEGER} AS INTEGER)


    and t.current_step_id = #{currentStepId}


    and t.id = #{orderId}


    and t.is_finished = #{isFinished}


    and t.current_step_name = #{currentStepName}


    and t.pm_type = #{pmType}


    and t.pm_num = #{pmNum}


    and t.status = #{status}


  and t.plan_time >= #{planTimeGTE}


  and t.plan_time <= #{planTimeLTE}


    and a.uid = #{queryAssetUid}


    and a.site_uid = #{assetInfoSiteUID}


    and T.id IN

        #{item}



    and a.clinical_dept_uid IN

        #{item}


  and T.asset_uid IN (
    SELECT DISTINCT COALESCE(mvs.mvs_ib_uid, mvs.e_home_ib_uid) AS mvs_ib_uid
    FROM asset_info ai
             JOIN user_org uo ON uo.org_uid IN (ai.tenant_uid, ai.institution_uid, ai.hospital_uid, ai.site_uid, ai.clinical_dept_uid)
             LEFT JOIN mvs_ib_mapping mvs ON ai.id = mvs.ib_id
    WHERE 1=1

    AND uo.user_uid = #{userUid}


    AND ai.tenant_uid = #{tenantUid}


    AND ai.name like CONCAT('%', #{assetName}, '%')


    AND ai.serial_num like CONCAT('%', #{assetSerialNum}, '%')


    AND ai.depart_num like CONCAT('%', #{departNum}, '%')


    and ai.asset_type IN

        #{item}



    AND ai.function_type  like CONCAT('%', #{functionType}, '%')

      AND ai.is_valid
      AND NOT ai.is_deleted
      AND (mvs.mvs_ib_uid IS NOT NULL OR mvs.e_home_ib_uid IS NOT NULL)
)
order by t.plan_time desc
